import{_ as i,C as r,o as s,c as l,j as a,a as t,b as h,w as n,E as c,a3 as d,a4 as u}from"./chunks/framework.D-V5jUSB.js";const k=JSON.parse('{"title":"Trust mechanics","description":"","frontmatter":{},"headers":[],"relativePath":"en/trust.md","filePath":"en/trust.md"}'),m={name:"en/trust.md"};function p(g,e,f,v,y,w){const o=r("Mermaid");return s(),l("div",null,[e[1]||(e[1]=a("h1",{id:"trust-mechanics",tabindex:"-1"},[t("Trust mechanics "),a("a",{class:"header-anchor",href:"#trust-mechanics","aria-label":'Permalink to "Trust mechanics"'},"​")],-1)),e[2]||(e[2]=a("p",null,[t("AI film search can't be a black box. This prototype adds guardrails in four places so editors can "),a("strong",null,"trust"),t(" every result — it explains itself when it finds something, says so honestly when it doesn't, measures its own quality, and keeps a human at the final gate.")],-1)),e[3]||(e[3]=a("h2",{id:"anti-hallucination-—-only-real-tags-allowed",tabindex:"-1"},[t("Anti-hallucination — only real tags allowed "),a("a",{class:"header-anchor",href:"#anti-hallucination-—-only-real-tags-allowed","aria-label":'Permalink to "Anti-hallucination — only real tags allowed"'},"​")],-1)),e[4]||(e[4]=a("p",null,"When the AI tags a film, it can only pick from the 14-dim / 400-tag list. Invented tags (not in the list) are dropped at the validation gate and never reach the database.",-1)),(s(),h(d,null,{default:n(()=>[c(o,{id:"mermaid-12",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20G%5B%22AI-suggested%20tags%22%5D%20--%3E%20V%5B%22tag%20registry%20whitelist%22%5D%0A%20%20%20%20V%20--%3E%7Cin%20list%7C%20OK%5B%22%E2%9C%85%20written%22%5D%0A%20%20%20%20V%20--%3E%7Cnot%20in%20list%7C%20X%5B%22%F0%9F%97%91%EF%B8%8F%20dropped%22%5D%0A%20%20%20%20classDef%20llm%20fill%3A%23f26f21%2Cstroke%3A%23d4570c%2Ccolor%3A%23000%0A%20%20%20%20class%20G%20llm%0A"})]),fallback:n(()=>[...e[0]||(e[0]=[t(" Loading... ",-1)])]),_:1})),e[5]||(e[5]=u('<h2 id="explainable-—-every-film-says-why-this-one" tabindex="-1">Explainable — every film says &quot;why this one&quot; <a class="header-anchor" href="#explainable-—-every-film-says-why-this-one" aria-label="Permalink to &quot;Explainable — every film says &quot;why this one&quot;&quot;">​</a></h2><p>Each result card states <strong>which conditions matched</strong> and <strong>how it was found</strong>:</p><blockquote><p><code>matches [music][american] · semantic+guess+literal</code></p></blockquote><p>Which tags hit, whether via semantic proximity, HyDE guess, or literal match — readable at a glance, no guessing.</p><h2 id="honest-score-—-says-so-when-there-s-no-match" tabindex="-1">Honest score — says so when there&#39;s no match <a class="header-anchor" href="#honest-score-—-says-so-when-there-s-no-match" aria-label="Permalink to &quot;Honest score — says so when there&#39;s no match&quot;">​</a></h2><p>Internal ranking scores are relative; without calibration the &quot;top of this batch&quot; always shows 100%, even when nothing is relevant. A confidence gate blocks that fake perfection: on no true match it raises a warning and lowers scores, while still offering the AI&#39;s best guesses for the editor to riff on.</p><p>Full mechanics plus a real &quot;fake 100%&quot; incident → <a href="/film-brain/vp-preview/en/honest">Honest score</a>.</p><h2 id="continuous-eval-—-every-change-gets-scored-no-vibes" tabindex="-1">Continuous eval — every change gets scored, no vibes <a class="header-anchor" href="#continuous-eval-—-every-change-gets-scored-no-vibes" aria-label="Permalink to &quot;Continuous eval — every change gets scored, no vibes&quot;">​</a></h2><p>An automated harness over 45 real queries (LLM-as-judge grading top-5) measures every change; winners stay, losers roll back. Top-5 hit quality lands at nDCG@5 ≈ 0.92–0.96.</p><p>How the self-eval loop works → <a href="/film-brain/vp-preview/en/self-eval">Self-eval loop</a>; the full v1–v8 iterations → <a href="/film-brain/vp-preview/en/eval">Eval</a>.</p><h2 id="human-in-the-loop-—-ai-navigates-humans-hold-taste" tabindex="-1">Human in the loop — AI navigates, humans hold taste <a class="header-anchor" href="#human-in-the-loop-—-ai-navigates-humans-hold-taste" aria-label="Permalink to &quot;Human in the loop — AI navigates, humans hold taste&quot;">​</a></h2><p>The AI reads, tags, and ranks; editors approve / reject / modify each one. Rejected tags aren&#39;t lost — they feed a <strong>feedback wiki</strong> the AI periodically digests (&quot;which tags get rejected, and why&quot;) to drive the next round. The final gate on taste is always human.</p>',12))])}const A=i(m,[["render",p]]);export{k as __pageData,A as default};
